use std::{fs,path::Path};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/fq6-toom175");assert!(!r.join("initial-native").exists());fs::rename(r.join("native"),r.join("initial-native")).unwrap();for f in["native.rs","build-plan.json","build-pins.json","design.md"]{fs::copy(r.join(f),r.join(format!("{f}.initial"))).unwrap();}let p=r.join("native.rs");let s=fs::read_to_string(&p).unwrap();assert_eq!(s.matches("lto=fat").count(),1);fs::write(&p,s.replace("lto=fat","lto=off")).unwrap();let d=r.join("design.md");let mut s=fs::read_to_string(&d).unwrap();s+="\nPre-capture linker repair: initial OFF field33tests, library build and freeze succeeded and are reused without rerunning. The initial harness failed before executing because Arkworks dev-dependency objects have no embedded LTO bitcode. All three component harnesses use lto=off, with original native optimized field libraries and identical flags otherwise. This is an actual field-library component call, not SDK-fat-LTO qualification. Original9step plan and failure retained; repaired6step workflow linksOFF, tests/builds/freezes/linksON and linksfrozen. No measured observation, successful test or successful library build repeated.\n";fs::write(d,s).unwrap();let mut plan:Value=serde_json::from_slice(&fs::read(r.join("build-plan.json")).unwrap()).unwrap();plan["steps"]=json!(plan["steps"].as_array().unwrap().iter().filter(|v|!["field-off","libraries-off","freeze-off"].contains(&v["name"].as_str().unwrap())).cloned().collect::<Vec<_>>());fs::write(r.join("build-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();}
